struct cfgfile dummy_cfg = {
    .filename = "fuzzer",
    .content = (const char *)data,
    .size = size,
};
if (size < 50)
  return 0;
parse_cfg(&dummy_cfg);

const char *errptr;
err = parse_line(line, outline, &outlen, args, &arg,
                 PARSE_OPT_ENV | PARSE_OPT_DQUOTE | PARSE_OPT_SQUOTE |
                 PARSE_OPT_BKSLASH | PARSE_OPT_SHARP | PARSE_OPT_WORD_EXPAND,
                 &errptr);

case 'x':
	if (!ishex(in[2]) || !ishex(in[3])) {
		err |= PARSE_ERR_HEX;
		if (errptr)
			*errptr = in;
		goto leave;
	}
	hex1 = toupper((unsigned char)in[2]) - '0';
	hex2 = toupper((unsigned char)in[3]) - '0';
	if (hex1 > 9) hex1 -= 'A' - '9' - 1;
	if (hex2 > 9) hex2 -= 'A' - '9' - 1;
	tosend = (hex1 << 4) + hex2;
	in += 3;
	break;

if (!prev_in_arg && in_arg) {
	begin_new_arg = curr_in;
	if (arg < argsmax)
		args[arg] = out + arg_start;
	else
		err |= PARSE_ERR_TOOMANY;
}

if (in_arg) {
	if (!empty_arg_ptr && args[arg] == out + arg_start)
		empty_arg_ptr = begin_new_arg;

if (pos >= width) {
	shift = pos - width / 2;
	in += shift + 3;
	end = out + width - 3;
	out[0] = out[1] = out[2] = '.';
	out += 3;
}
